export const getActionModifyClusterSnapshotRoute = createRoute({
  method: 'get',
  path: '/#Action=ModifyClusterSnapshot',
  description:
    '<p>Modifies the settings for a snapshot.</p> <p>This exanmple modifies the manual retention period setting for a cluster snapshot.</p>',
  operationId: 'GET_ModifyClusterSnapshot',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      SnapshotIdentifier: z
        .string()
        .max(2147483647)
        .openapi({
          param: {
            name: 'SnapshotIdentifier',
            in: 'query',
            required: true,
            description: 'The identifier of the snapshot whose setting you want to modify.',
            schema: { type: 'string', maxLength: 2147483647 },
          },
        }),
      ManualSnapshotRetentionPeriod: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ManualSnapshotRetentionPeriod',
            in: 'query',
            required: false,
            description:
              '<p>The number of days that a manual snapshot is retained. If the value is -1, the manual snapshot is retained indefinitely.</p> <p>If the manual snapshot falls outside of the new retention period, you can specify the force option to immediately delete the snapshot.</p> <p>The value must be either -1 or an integer between 1 and 3,653.</p>',
            schema: { type: 'integer' },
          },
        }),
      Force: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'Force',
            in: 'query',
            required: false,
            description:
              'A Boolean option to override an exception if the retention period has already passed.',
            schema: { type: 'boolean' },
          },
        }),
      Action: z
        .literal('ModifyClusterSnapshot')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['ModifyClusterSnapshot'] },
          },
        }),
      Version: z
        .literal('2012-12-01')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2012-12-01'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: ModifyClusterSnapshotResultSchema } },
    },
    480: {
      description: 'InvalidClusterSnapshotStateFault',
      content: { 'text/xml': { schema: InvalidClusterSnapshotStateFaultSchema } },
    },
    481: {
      description: 'ClusterSnapshotNotFoundFault',
      content: { 'text/xml': { schema: ClusterSnapshotNotFoundFaultSchema } },
    },
    482: {
      description: 'InvalidRetentionPeriodFault',
      content: { 'text/xml': { schema: InvalidRetentionPeriodFaultSchema } },
    },
  },
})

